_filter_url as $url) { if ($pos===false) $pos = strpos($image_url, $url); } $this->watermark_allowed = $pos===false && in_array('collection', $this->options->qc_watermark_enabled_for); } else $this->watermark_allowed = false; if (defined('COLLECTING') || isset($_POST['action']) && in_array($_POST['action'], array('manual_save_remote_images', 'editpost'))) { return is_array($this->options->qc_watermark_enabled_for) && in_array('collection', $this->options->qc_watermark_enabled_for) ? $this->watermark_allowed : false; } elseif (isset($_POST['action']) && $_POST['action'] == 'upload-attachment' && isset($_POST['post_id'])) { return is_array($this->options->qc_watermark_enabled_for) && in_array('edit-page', $this->options->qc_watermark_enabled_for) ? true : false; } else { return is_array($this->options->qc_watermark_enabled_for) && in_array('media-library', $this->options->qc_watermark_enabled_for) ? true : false; } } public function add_watermark_when_upload($metadata, $attachment_id) { do_action( 'qqworld-collector-add-watermark-when-upload', $metadata, $attachment_id, array($this) ); return $metadata; } public function no_media_library_attachment($remote_attachment, $type) { $remote_attachment = apply_filters( 'qqworld-collector-add-watermark-when-no-media-library', $remote_attachment, $type, array($this) ); return $remote_attachment; } public function save_watermark($image_path) { ob_start(); $this->add_watermark($image_path, null, 'save'); $image = ob_get_contents(); ob_end_clean(); if (!empty($image)) { $fp = fopen($image_path, "wb"); fwrite($fp, $image); fclose($fp); } } public function preview_watermark() { if (isset($_GET['align_to'])) $this->options->qc_watermark_image_align_to = $_GET['align_to']; if (isset($_GET['offset'])) $this->options->qc_watermark_image_offset = array('x'=>$_GET['offset']['x'],'y'=>$_GET['offset']['y']); if (isset($_GET['opacity'])) $this->options->qc_watermark_image_opacity = $_GET['opacity']; if (isset($_GET['mode'])) $this->options->qc_watermark_image_mode = $_GET['mode']; $this->image_path = QQWORLD_OUTSIDE_COLLECTOR_DIR . 'images' . DIRECTORY_SEPARATOR . 'watermark' . DIRECTORY_SEPARATOR . 'photo.jpg'; $this->get_watermark_filepath(); if (isset($this->watermark_path) && $this->watermark_path) $this->add_watermark($this->image_path, $this->watermark_path); exit; } public function get_watermark_attachments_list() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) exit; $paged = $_REQUEST['paged']; $args = array( 'post_type' => 'attachment', 'post_mime_type' => 'image', 'meta_key' => '_added_watermark', 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); $attachments = get_posts($args); if (!empty($attachments)) { $success_message = sprintf(_n('%d no watermark attachment found, processing...', '%d no watermark attachments found, processing...', count($attachments), $this->text_domain), count($attachments)); $array = array(); foreach ($attachments as $attachment) $array[] = $attachment->ID; $results = array( 'success' => 1, 'msg' => $success_message, 'attachments' => $array ); } else { $failed_message = __('Congratulations, seems like all attachments had already processed.', $this->text_domain); $results = array( 'success' => 0, 'msg' => $failed_message ); } echo json_encode($results); exit; } public function add_watermark_to_attachment() { if (!isset($_POST['attachment_id']) || empty($_POST['attachment_id'])) return; $attachment_id = $_POST['attachment_id']; $attachment = get_post($attachment_id); $type = $attachment->post_mime_type; $metadata = wp_get_attachment_metadata($attachment_id); $full_size = wp_get_attachment_image_src($attachment_id, 'full'); $thumbnail_size = wp_get_attachment_image_src($attachment_id); $results = array( 'type' => $type, 'sizes' => array( 'full' => $full_size, 'thumbnail' => $thumbnail_size ) ); do_action( 'qqworld-collector-add-watermark-when-upload', $metadata, $attachment_id, array($this)