mageSY($watermark); list($r, $g, $b) = $this->hex2rgb($this->options->qc_watermark_text_bgcolor); $gray = imagecolorallocate($watermark, $r, $g, $b); imageellipse($watermark, $banner_height/2, $banner_height/2, $banner_height, $banner_height, $gray); imagefill($watermark, $banner_height, 0, $gray); imagefill($watermark, $banner_height/2, $banner_height/2, $gray); $alpha = imagecolorallocatealpha($watermark, 0, 0, 0, 127); imagefill($watermark, 0, 0, $alpha); imagefill($watermark, 0, $banner_height-1, $alpha); $x = $image_width - $banner_width; $y = $image_height - $banner_height - $margin_bottom; if ($this->options->qc_watermark_text_bg_mosaics) $this->add_mosaics($x+20, $y, $image_width, $image_height-$margin_bottom, 15); $temp = imagecreatetruecolor($cover_watermark_width, $cover_watermark_height); imagecopy($temp, $this->image, 0, 0, $x, $y, $cover_watermark_width, $cover_watermark_height); imagecopy($temp, $watermark, 0, 0, 0, 0, $cover_watermark_width, $cover_watermark_height); imagecopymerge($this->image, $temp, $x, $y, 0, 0, $cover_watermark_width, $cover_watermark_height, $this->options->qc_watermark_text_bg_opacity); $font = WP_CONTENT_DIR . '/font/' .$this->options->qc_watermark_text_font; $text = $this->options->qc_watermark_text_content; if ($text && file_exists($font)) { $box = imagettfbbox($font_size, 0, $font, $text); $font_width = $box[4] - $box[6]; $font_x = $image_width - $font_width - 10; $font_y = $image_height - $margin_bottom - $fix_bottom; list($r, $g, $b) = $this->hex2rgb($this->options->qc_watermark_text_font_color); $color = imagecolorallocate($this->image, $r, $g, $b); imagefttext($this->image, $font_size, 0, $font_x, $font_y, $color, $font, $text); } $this->is_added_watermark = true; } if ($this->options->qc_watermark_image_enabled) { $limit_width = $image_width * $this->options->qc_watermark_image_width_limit / 100; if ($watermark_width > $limit_width) { $target_watermark_width = $limit_width; $target_watermark_height = $watermark_height * $limit_width / $watermark_width; $temp = imagecreatetruecolor($watermark_width, $watermark_height); if ($this->watermark_data['mime'] == 'image/png') { $alpha = imagecolorallocatealpha($temp, 0, 0, 0, 127); imagefill($temp, 0, 0, $alpha); } imagecopyresampled($temp, $this->watermark, 0, 0, 0, 0, $target_watermark_width, $target_watermark_height, $watermark_width, $watermark_height); if ($this->watermark_data['mime'] == 'image/png') { imagesavealpha($temp, true); ob_start(); ImagePng($temp); $temp = ob_get_contents(); ob_end_clean(); $temp = imageCreateFromString($temp); } $this->watermark = $temp; $watermark_width = $target_watermark_width; $watermark_height = $target_watermark_height; } $full_offset_x = $image_width - $watermark_width; $full_offset_y = $image_height - $watermark_height; $half_offset_x = ($image_width - $watermark_width)/2; $half_offset_y = ($image_height - $watermark_height)/2; switch ($this->options->qc_watermark_image_mode) { case 'normal': $offset = $this->options->qc_watermark_image_offset; switch ($this->options->qc_watermark_image_align_to) { case 'lt': $x = $offset['x']; $y = $offset['y']; break; case 'ct': $x = $half_offset_x+$offset['x']; $y = $offset['y']; break; case 'rt': $x = $offset['x']+$full_offset_x; $y = $offset['y']; break; case 'lc': $x = $offset['x']; $y = $offset['y']+$half_offset_y; break; case 'cc': $x = $offset['x']+$half_offset_x; $y = $offset['y']+$half_offset_y; break; case 'rc': $x = $offset['x']+$full_offset_x; $y = $offset['y']+$half_offset_y; break; case 'lb': $x = $offset['x']; $y = $offset['y']+$full_offset_y; break; case 'cb': $x = $offset['x']+$half_offset_x; $y = $offset['y']+$full_offset_y; break; case 'rb': $x = $offset['x']+$full_offset_x; $y = $offset['y']+$full_offset_y; break; } break; case 'random-position': $random_full_offset_x = $full_offset_x - 40; $random_full_offset_y = $full_offset_y - 40; $x = rand(20, $random_full_offset_x); $y = rand(20, $random_full_offset_y); break; case 'repeat-covered': $cols = ceil($image_width / $watermark_width); $rows = ceil($image_height / $watermark_height); for ($c=0; $c<$cols; $c++) { for ($r=0; $r<$rows; $r++) { $x = $c * $watermark_width; $y = $r * $watermark_height; $temp = imagecreatetruecolor($watermark_width, $watermark_height); imagecopy($temp, $this->image, 0, 0, $x, $y, $watermark_width, $watermark_height); imagecopy($temp, $this->watermark, 0, 0, 0, 0, $watermark_width, $watermark_height); imagecopymerge($this->image, $temp, $x, $y, 0, 0, $watermark_width, $watermark_height, $this->options->qc_watermark_image_opacity); } } break; } if ($this->options->qc_watermark_image_mode != 'repeat-covered') { $temp = imagecreatetruecolor($watermark_width, $watermark_height); imagecopy($temp, $this->image, 0, 0, $x, $y, $watermark_width, $watermark_height); imagecopy($temp, $this->watermark, 0, 0, 0, 0, $watermark_width, $watermark_height); imagecopymerge($this->image, $temp, $x, $y, 0, 0, $watermark_width, $watermark_height, $this->options->qc_watermark_image_opacity); } $this->is_added_watermark = true; } switch ($type) { case 'show': $this->process_image(); break; case 'save': $this->process_image('save', $image_path); break; case 'return': return $this->process_image('return'); break; } } public function process_image($type='show', $image_path = null) { if ($type == 'show') header ("Content-type: ".$this->image_data["mime"]); if ($type == 'return') ob_start(); switch ($this->image_data["mime"]) { case 'image/png': $level = ($this->options->qc_compression_quality - 100) / 11.111111; $level = round(abs($level)); imagealphablending($this->image, false); imagesavealpha($this->image, true); ImagePng($this->image, $image_path, $level, PNG_ALL_FILTERS); break; case 'image/jpeg': ImageJpeg($this->image, $image_path, $this->options->qc_compression_quality); break; case 'image/gif': ImageGif($this->image, $image_path); break; } ImageDestroy($this->image); ImageDestroy($this->watermark); if ($type == 'return') { $image = ob_get_contents(); ob_end_clean(); return $image; } } } ?>